-- supabase/migrations/20260910200000_add_aria_care_learning_contexts.sql
CREATE TABLE IF NOT EXISTS public.aria_care_contexts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id text NOT NULL, person_id uuid NOT NULL REFERENCES public.people(id) ON DELETE CASCADE, kind text NOT NULL, starts_on date NOT NULL DEFAULT CURRENT_DATE, ends_on date, service_type text, note text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT aria_care_contexts_kind_check CHECK (kind IN ('travel','temporary_unavailable','preferred_service','not_attending','other')), CONSTRAINT aria_care_contexts_dates_check CHECK (ends_on IS NULL OR ends_on >= starts_on));
CREATE INDEX IF NOT EXISTS idx_aria_care_contexts_person_active ON public.aria_care_contexts (organization_id,person_id,ends_on);
CREATE INDEX IF NOT EXISTS idx_aria_care_contexts_service ON public.aria_care_contexts (organization_id,service_type,ends_on);